import{_ as t,o as i,c as r,a3 as a}from"./chunks/framework.BwzYn71E.js";const f=JSON.parse('{"title":"完美的终末地工业模拟代码","description":"","frontmatter":{"translationSource":{"title":"完美的终末地工业模拟代码","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=y1xZXtulUCeVfPPJumEMg3","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/perfect-endfield-industrial-simulation-code"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/perfect-endfield-industrial-simulation-code"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/perfect-endfield-industrial-simulation-code"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/perfect-endfield-industrial-simulation-code"}]]},"headers":[],"relativePath":"zh/perfect-endfield-industrial-simulation-code.md","filePath":"zh/page-y1xZXtulUCeVfPPJumEMg3.md"}'),n={name:"zh/perfect-endfield-industrial-simulation-code.md"};function d(p,e,o,l,s,c){return i(),r("div",null,[...e[0]||(e[0]=[a('<div class="logistics-content"><span class="logistics-source-anchor" id="完美的终末地工业模拟代码" aria-hidden="true"></span><h1 id="完美的终末地工业模拟代码" tabindex="-1">完美的终末地工业模拟代码 <a class="header-anchor" href="#完美的终末地工业模拟代码" aria-label="Permalink to &quot;完美的终末地工业模拟代码&quot;">​</a></h1><blockquote><p>源页面 ID：<code>y1xZXtulUCeVfPPJumEMg3</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=y1xZXtulUCeVfPPJumEMg3" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>目前所有的模拟都存在各种缺陷，这里举出群友的模拟代码以期待相互启发</p><p>苍孤狼 的模拟代码<br><a href="https://github.com/hxcgl/Endfield_EWMA-filter.git" target="_blank" rel="noreferrer">https://github.com/hxcgl/Endfield_EWMA-filter.git</a></p><p>madSUN 的模拟代码</p><p><a href="https://github.com/hongshan-academy/endfield-AIC-sim" target="_blank" rel="noreferrer">https://github.com/hongshan-academy/endfield-AIC-sim</a></p><p><a href="https://github.com/madSUNitist/endfield-AIC-simulation-v2" target="_blank" rel="noreferrer">GitHub - madSUNitist/endfield-AIC-simulation-v2: 新想法，新框架😋 · GitHub</a></p><p>由于原链接的readme文档绘图错误，这里提供一个可读性更好的readme文档（保存到本地md文档）</p><p><a href="/endfield-skydoc/zh/readme-madsun">README-madSUN</a></p><p>伸手党 的模拟代码</p><p><a href="https://github.com/FrozenStream/endfield-sim" target="_blank" rel="noreferrer">https://github.com/FrozenStream/endfield-sim</a></p><p>jnk 的思路伪代码</p><p><a href="/endfield-skydoc/zh/jnks-pseudocode">jnk 的伪代码</a></p><p>完美代码应当能够实现以下特性</p><p><em><strong>简单</strong></em>：</p><p>分流器与汇流器与大部分工厂的231轮询</p><p>满环不动</p><p>协议箱的123轮询</p><p><em><strong>标准：</strong></em></p><p>优先输出-完成阻尼理论所描述的工厂优先输出逻辑</p><p>优先汇入-完成汇流器分流器直连优先级（分流器无其他路径且汇流器不在环上版本</p><p>先进后出-协议箱先入后出与协议箱单空同时动双环等现象</p><p>侧面优先-多数工厂与取货口处直连的汇流器其他输入优先级</p><p><em><strong>进阶：</strong></em></p><p>优先输出进阶-完成阻尼理论中的bug：单传送带物流线的优先级异常；完成工厂入口处分流器导致的优先级现象</p><p>优先汇入进阶-完成汇流器分流器直连时的优先级现象</p><p>迟滞输出-实现4n卡1s的类似效果，不考虑其输出与优先汇入的联动</p><p>独特水管-额外实现水管的效果，水管无法容纳多种液体</p><p><em><strong>困难：</strong></em></p><p>优先完全-完成反应池等特殊工厂不触发优先输出等优先级问题的实现</p><p>迟滞输出进阶-完成4n卡1s，包括其与优先汇入的联动效果等，并完成水管版本的2n卡1格</p><p>其他后置任务</p><p>闰年规则限流法实现完美均匀有理数输出器的相关模拟验证</p></div>',1)])])}const m=t(n,[["render",d]]);export{f as __pageData,m as default};
